krpano.action:
addhotspot(%4);
set(hotspot[%4].malo, %3);

set(hotspot[%4].islot, true);
set(hotspot[%4].type, text);
set(hotspot[%4].html, %3);
set(hotspot[%4].ath, %1);
set(hotspot[%4].atv, %2);
set(hotspot[%4].edge, center);
set(hotspot[%4].distorted, false);
set(hotspot[%4].zoom, false);
set(hotspot[%4].bg, true);
set(hotspot[%4].bgcolor, 0x0D2620);
set(hotspot[%4].bgalpha, 0.80);
set(hotspot[%4].bgroundedge, 9);
set(hotspot[%4].bgborder, '1 0x7ADD8B 0.80');
set(hotspot[%4].bgshadow, '0 1 5 0x000000 0.50');
set(hotspot[%4].padding, '3 8 3 8');
set(hotspot[%4].css, 'color:#EDF8EF; font-family:Inter, Arial, sans-serif; font-size:11px; font-weight:700; letter-spacing:0.3px; white-space:nowrap;');
set(hotspot[%4].handcursor, true);
set(hotspot[%4].zorder, 60);
set(hotspot[%4].onover,  era_lot_over(); );
set(hotspot[%4].onout,   era_lot_out(); );
set(hotspot[%4].onclick, era_lot_clicked(); );
set(hotspot[%4].ondown,  era_lot_down(); );
set(hotspot[%4].onup,    era_lot_up(); );

set(lots_ui_built, true);
set(lots_edit_on, false);
set(lots_add_mode, false);

addlayer(lots_edit_btn);
set(layer[lots_edit_btn].type, text);
set(layer[lots_edit_btn].align, rightbottom); set(layer[lots_edit_btn].edge, rightbottom);
set(layer[lots_edit_btn].x, 16); set(layer[lots_edit_btn].y, 16);
set(layer[lots_edit_btn].bg, true); set(layer[lots_edit_btn].bgcolor, 0x0D2620);
set(layer[lots_edit_btn].bgalpha, 0.85); set(layer[lots_edit_btn].bgroundedge, 9);
set(layer[lots_edit_btn].bgborder, '1 0xCBF0D6 0.25');
set(layer[lots_edit_btn].padding, '8 13 8 13'); set(layer[lots_edit_btn].handcursor, true);
set(layer[lots_edit_btn].css, 'color:#EDF8EF; font-family:Inter, Arial, sans-serif; font-size:12px; font-weight:700;');
set(layer[lots_edit_btn].html, 'ĐẶT MÃ LÔ (L)');
set(layer[lots_edit_btn].zorder, 220);
set(layer[lots_edit_btn].keep, true); set(layer[lots_edit_btn].visible, false);
set(layer[lots_edit_btn].onclick, era_lots_toggle_edit(); );

era_lots_btn(lots_add_btn,  56, 0x1565C0, '+ ĐẶT LÔ MỚI',  era_lots_arm() );
era_lots_btn(lots_del_btn,  96, 0x8A1020, 'XOÁ LÔ VỪA ĐẶT',   era_lots_del_last() );
era_lots_btn(lots_auto_btn,136, 0x6B4FBB, 'GỢI Ý TỰ ĐỘNG',    era_lots_auto() );
era_lots_btn(lots_exp_btn, 176, 0x1B9E5A, 'XUẤT CODE',        era_lots_export() );

addlayer(lots_readout);
set(layer[lots_readout].type, text);
set(layer[lots_readout].align, top); set(layer[lots_readout].y, 16);
set(layer[lots_readout].bg, true); set(layer[lots_readout].bgcolor, 0x0D2620);
set(layer[lots_readout].bgalpha, 0.90); set(layer[lots_readout].bgroundedge, 10);
set(layer[lots_readout].bgborder, '1 0xCBF0D6 0.20');
set(layer[lots_readout].padding, '10 18 10 18'); set(layer[lots_readout].enabled, false);
set(layer[lots_readout].css, 'color:#EDF8EF; font-family:Inter, Arial, sans-serif; font-size:13px; text-align:center;');
set(layer[lots_readout].html, '');
set(layer[lots_readout].zorder, 221);
set(layer[lots_readout].keep, true); set(layer[lots_readout].visible, false);

addlayer(%1);
set(layer[%1].type, text);
set(layer[%1].align, rightbottom); set(layer[%1].edge, rightbottom);
set(layer[%1].x, 16); set(layer[%1].y, %2);
set(layer[%1].bg, true); set(layer[%1].bgcolor, %3);
set(layer[%1].bgalpha, 0.95); set(layer[%1].bgroundedge, 9);
set(layer[%1].padding, '8 13 8 13'); set(layer[%1].handcursor, true);
set(layer[%1].css, 'color:#FFFFFF; font-family:Inter, Arial, sans-serif; font-size:12px; font-weight:700;');
set(layer[%1].html, %4);
set(layer[%1].zorder, 220);
set(layer[%1].keep, true); set(layer[%1].visible, false);
set(layer[%1].onclick, %5);

if(lots_edit_on == true,
  set(lots_edit_on, false);
  set(lots_add_mode, false);
  era_lots_editui(false);
  set(layer[lots_edit_btn].bgcolor, 0x0D2620);
  set(layer[lots_edit_btn].html, 'ĐẶT MÃ LÔ (L)');
,
  set(lots_edit_on, true);
  set(lots_add_mode, false);
  era_lots_editui(true);
  set(layer[lots_readout].html, 'CHẾ ĐỘ ĐẶT · bấm ĐẶT LÔ MỚI rồi click lên ảnh · kéo gim để chỉnh');
  set(layer[lots_edit_btn].bgcolor, 0xC8102E);
  set(layer[lots_edit_btn].html, 'XONG (L)');
);

if(lots_edit_on == true,
  set(lots_add_mode, true);
  set(layer[lots_readout].html, 'CLICK lên ảnh tại vị trí lô cần gim (1 lần)');
);

if(lots_edit_on == true,
  if(lots_add_mode == true,
    screentosphere(mouse.x, mouse.y, lk_ath, lk_atv);
    set(lots_add_mode, false);
    set(layer[lots_readout].html, 'Chọn mã lô trong cửa sổ...');
    js( eraLotPick(get(lk_ath), get(lk_atv)) );
  );
);

for(set(i, hotspot.count), i GT 0, dec(i),
  set(j, calc(i - 1));
  if(hotspot[get(j)].islot == true, removehotspot(get(hotspot[get(j)].name)); );
);

set(sdraft, '');
for(set(i, 0), i LT hotspot.count, inc(i),
  if(hotspot[get(i)].islot == true,
    txtadd(sdraft, get(sdraft), get(hotspot[get(i)].ath));
    txtadd(sdraft, get(sdraft), '|');
    txtadd(sdraft, get(sdraft), get(hotspot[get(i)].atv));
    txtadd(sdraft, get(sdraft), '|');
    txtadd(sdraft, get(sdraft), get(hotspot[get(i)].malo));
    txtadd(sdraft, get(sdraft), '|');
    txtadd(sdraft, get(sdraft), get(hotspot[get(i)].name));
    txtadd(sdraft, get(sdraft), '###');
  );
);
js( eraLotSave(get(sdraft)) );

set(exp, '');
for(set(i, 0), i LT hotspot.count, inc(i),
  if(hotspot[get(i)].islot == true,
    txtadd(exp, get(exp), '  era_lot( ');
    txtadd(exp, get(exp), get(hotspot[get(i)].ath));
    txtadd(exp, get(exp), ', ');
    txtadd(exp, get(exp), get(hotspot[get(i)].atv));
    txtadd(exp, get(exp), ", '");
    txtadd(exp, get(exp), get(hotspot[get(i)].malo));
    txtadd(exp, get(exp), "', ");
    txtadd(exp, get(exp), get(hotspot[get(i)].name));
    txtadd(exp, get(exp), ' );###');
  );
);
js( eraLotExport(get(exp)) );
trace(get(exp));

era_lots_ui_build();
if(xml.scene == 'scene_matbang_flycam',
  set(layer[lots_edit_btn].visible, true);
  js( eraLotRestore() );
,
  set(lots_edit_on, false);
  set(lots_add_mode, false);
  era_lots_editui(false);
  set(layer[lots_edit_btn].visible, false);
  set(layer[lots_edit_btn].bgcolor, 0x0D2620);
  set(layer[lots_edit_btn].html, 'ĐẶT MÃ LÔ (L)');
  js( lotOut() );
);
